8	#[derive(Debug, Clone, Default)]
9	pub(crate) struct FormatJsCaseClause;
10	
11	impl FormatNodeRule<JsCaseClause> for FormatJsCaseClause {
12	    fn fmt_fields(&self, node: &JsCaseClause, f: &mut JsFormatter) -> FormatResult<()> {
13	        let JsCaseClauseFields {
14	            case_token,
15	            test,
16	            colon_token,
17	            consequent,
18	        } = node.as_fields();
19	
20	        write!(
21	            f,
22	            [
23	                case_token.format(),
24	                space(),
25	                test.format(),
26	                colon_token.format()
27	            ]
28	        )?;
29	
30	        // Whether the first statement in the clause is a BlockStatement, and
31	        // there are no other non-empty statements. Empties may show up when
32	        // parsing depending on if the input code includes certain newlines.
33	        let is_single_block_statement = matches!(
34	            consequent.iter().next(),
35	            Some(AnyJsStatement::JsBlockStatement(_))
36	        ) && consequent
37	            .iter()
38	            .filter(|statement| !matches!(statement, AnyJsStatement::JsEmptyStatement(_)))
39	            .count()
40	            == 1;
41	
42	        // When the case block is empty, the case becomes a fallthrough, so it
43	        // is collapsed directly on top of the next case (just a single
44	        // hardline).
45	        // When the block is a single statement _and_ it's a block statement,
46	        // then the opening brace of the block can hug the same line as the
47	        // case. But, if there's more than one statement, then the block
48	        // _cannot_ hug. This distinction helps clarify that the case continues
49	        // past the end of the block statement, despite the braces making it
50	        // seem like it might end.
51	        // Lastly, the default case is just to break and indent the body.
52	        //
53	        // switch (key) {
54	        //   case fallthrough: // trailing comment
55	        //   case normalBody:
56	        //     someWork();
57	        //     break;
58	        //
59	        //   case blockBody: {
60	        //     const a = 1;
61	        //     break;
62	        //   }
63	        //
64	        //   case separateBlockBody:
65	        //     {
66	        //       breakIsNotInsideTheBlock();
67	        //     }
68	        //     break;
69	        //
70	        //   default:
71	        //     break;
72	        // }
73	        if consequent.is_empty() {
74	            // Print nothing to ensure that trailing comments on the same line
75	            // are printed on the same line. The parent list formatter takes
76	            // care of inserting a hard line break between cases.
77	            Ok(())
78	        } else if is_single_block_statement {
79	            write![f, [space(), consequent.format()]]
80	        } else {
81	            // no line break needed after because it is added by the indent in the switch statement
82	            write!(
83	                f,
84	                [indent(&format_args![
85	                    hard_line_break(),
86	                    consequent.format()
87	                ])]
88	            )
89	        }
90	    }
91	}
