399	/// Moves comments in declaration statements to behind the identifier
400	///
401	/// ```javascript
402	/// declare module /* comment */ A {}
403	/// declare /* module */ global {}
404	/// ```
405	fn handle_declare_comment(comment: DecoratedComment<JsLanguage>) -> CommentPlacement<JsLanguage> {
406	    match (comment.enclosing_node().kind(), comment.following_node()) {
407	        // Check if it is a declare statement
408	        (JsSyntaxKind::TS_DECLARE_STATEMENT, Some(following)) => {
409	            match following.kind() {
410	                JsSyntaxKind::TS_GLOBAL_DECLARATION => {
411	                    // Global declarations have no identifier, so keep at default
412	                    CommentPlacement::Default(comment)
413	                }
414	                JsSyntaxKind::TS_MODULE_DECLARATION
415	                | JsSyntaxKind::TS_ENUM_DECLARATION
416	                | JsSyntaxKind::TS_INTERFACE_DECLARATION
417	                | JsSyntaxKind::TS_DECLARE_FUNCTION_DECLARATION
418	                | JsSyntaxKind::TS_TYPE_ALIAS_DECLARATION => {
419	                    // Move comment after the module keyword
420	                    // This is the first child of the module declaration which is the identifier
421	                    if let Some(first_child) = following.first_child() {
422	                        return CommentPlacement::leading(first_child.clone(), comment);
423	                    }
424	                    CommentPlacement::Default(comment)
425	                }
426	                JsSyntaxKind::JS_CLASS_DECLARATION => {
427	                    if let Some(first_child) = following.first_child()
428	                        && let Some(second_child) = first_child.next_sibling()
429	                    {
430	                        return CommentPlacement::leading(second_child.clone(), comment);
431	                    }
432	                    CommentPlacement::Default(comment)
433	                }
434	                JsSyntaxKind::JS_VARIABLE_DECLARATION_CLAUSE => {
435	                    let first_identifier = following
436	                        .descendants()
437	                        .find(|node| node.kind() == JsSyntaxKind::JS_IDENTIFIER_BINDING);
438	                    if let Some(first_identifier_exists) = first_identifier {
439	                        return CommentPlacement::leading(first_identifier_exists.clone(), comment);
440	                    }
441	                    CommentPlacement::Default(comment)
442	                }
443	                _ => CommentPlacement::Default(comment),
444	            }
445	        }
446	        _ => CommentPlacement::Default(comment),
447	    }
448	}
